namespace sv_f17ad4d8663b4af29ea3ca0ee4c4b4f5.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies all subscribers when it changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
        ("WH-D", "Warehouse D"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId).Name
        ?? _currentWarehouseId;

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
            await OnWarehouseChanged.Invoke();
    }
}

namespace sv_f17ad4d8663b4af29ea3ca0ee4c4b4f5.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts on the current warehouse.
/// Notifies all subscribers when new data arrives so every component updates.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _activeSubscribers;

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever a new alert count is fetched. All subscribed components should re-render.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChangedAsync;
    }

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Call when a component that needs polling becomes active (e.g., OnInitialized).
    /// Polling starts on the first subscriber and stops when the last one leaves.
    /// </summary>
    public void StartPolling()
    {
        _activeSubscribers++;
        if (_activeSubscribers == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component that needs polling is disposed.
    /// </summary>
    public void StopPolling()
    {
        _activeSubscribers = Math.Max(0, _activeSubscribers - 1);
        if (_activeSubscribers == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await FetchAndNotifyAsync();

        while (_timer is not null)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(ct))
                    break;
            }
            catch (OperationCanceledException)
            {
                break;
            }

            await FetchAndNotifyAsync();
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertDataChanged is not null)
            await OnAlertDataChanged.Invoke();
    }

    private async Task HandleWarehouseChangedAsync()
    {
        // When warehouse changes, immediately refresh alert data
        if (_activeSubscribers > 0)
            await FetchAndNotifyAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChangedAsync;
        _cts?.Cancel();
        _timer?.Dispose();
    }
}

@using sv_f17ad4d8663b4af29ea3ca0ee4c4b4f5.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label class="text-white mb-0 fw-semibold" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChangedAsync">
        @foreach (var (id, name) in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private async Task OnWarehouseChangedAsync(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            await WarehouseState.SetWarehouseAsync(newId);
        }
    }

    private Task HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

@using sv_f17ad4d8663b4af29ea3ca0ee4c4b4f5.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge @BadgeClass rounded-pill">@AlertService.LatestLowStockCount</span>

@code {
    private string BadgeClass => AlertService.LatestLowStockCount switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        > 0 => "bg-info",
        _ => "bg-success"
    };

    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    private Task HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_f17ad4d8663b4af29ea3ca0ee4c4b4f5.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card border-warning">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @CountColor">@AlertService.LatestLowStockCount</p>
                <p class="text-muted small">Items below minimum level</p>
                <p class="text-muted small">Auto-refreshes every 10 seconds</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted small">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Last Updated</h5>
                <p class="display-6 fs-4">@_lastUpdated.ToString("HH:mm:ss")</p>
                <p class="text-muted small">Next poll in ~10s</p>
            </div>
        </div>
    </div>
</div>

@code {
    private DateTime _lastUpdated = DateTime.Now;

    private string CountColor => AlertService.LatestLowStockCount switch
    {
        > 10 => "text-danger",
        > 5 => "text-warning",
        > 0 => "text-info",
        _ => "text-success"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;

        // Start polling when this page becomes active
        AlertService.StartPolling();
    }

    private Task HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    private Task HandleAlertDataChanged()
    {
        _lastUpdated = DateTime.Now;
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;

        // Stop polling when user navigates away
        AlertService.StopPolling();
    }
}

