toolArgs.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@using sv_f17ad4d8663b4af29ea3ca0ee4c4b4f5.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card border-warning">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @CountColor">@AlertService.LatestLowStockCount</p>
                <p class="text-muted small">Items below minimum level</p>
                <p class="text-muted small">Auto-refreshes every 10 seconds</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted small">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Last Updated</h5>
                <p class="display-6 fs-4">@_lastUpdated.ToString("HH:mm:ss")</p>
                <p class="text-muted small">Next poll in ~10s</p>
            </div>
        </div>
    </div>
</div>

@code {
    private DateTime _lastUpdated = DateTime.Now;

    private string CountColor => AlertService.LatestLowStockCount switch
    {
        > 10 => "text-danger",
        > 5 => "text-warning",
        > 0 => "text-info",
        _ => "text-success"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;

        // Start polling when this page becomes active
        AlertService.StartPolling();
    }

    private Task HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    private Task HandleAlertDataChanged()
    {
        _lastUpdated = DateTime.Now;
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;

        // Stop polling when user navigates away
        AlertService.StopPolling();
    }
}

